module ShortestPathNodes(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] s,\n    input [2:0] t,\n    input [4:0] num_edges,\n    input [2:0] u [0:15],\n    input [2:0] v [0:15],\n    input [15:0] w [0:15],\n    output reg [7:0] mask,\n    output reg done\n);\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT_FORWARD = 3'd1;\n    localparam [2:0] RELAX_FORWARD = 3'd2;\n    localparam [2:0] INIT_BACKWARD = 3'd3;\n    localparam [2:0] RELAX_BACKWARD = 3'd4;\n    localparam [2:0] CHECK_NODES = 3'd5;\n    localparam [2:0] DONE = 3'd6;\n    \n    reg [2:0] state, next_state;\n    reg [31:0] dist_s [0:7];\n    reg [31:0] num_paths_s [0:7];\n    reg [31:0] dist_t [0:7];\n    reg [31:0] num_paths_t [0:7];\n    reg [31:0] total_dist;\n    reg [2:0] iteration_count;\n    reg [3:0] edge_index;\n    reg [2:0] node_index;\n    \n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            mask <= 8'd0;\n            iteration_count <= 3'd0;\n            edge_index <= 4'd0;\n            node_index <= 3'd0;\n            total_dist <= 32'hFFFF_FFFF;\n            for (i = 0; i < 8; i = i+1) begin\n                dist_s[i] <= 32'hFFFF_FFFF;\n                num_paths_s[i] <= 32'd0;\n                dist_t[i] <= 32'hFFFF_FFFF;\n                num_paths_t[i] <= 32'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    mask <= 8'd0;\n                    if (start) begin\n                        next_state <= INIT_FORWARD;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n                \n                INIT_FORWARD: begin\n                    for (i = 0; i < 8; i = i+1) begin\n                        if (i == s) begin\n                            dist_s[i] <= 32'd0;\n                            num_paths_s[i] <= 32'd1;\n                        end else begin\n                            dist_s[i] <= 32'hFFFF_FFFF;\n                            num_paths_s[i] <= 32'd0;\n                        end\n                    end\n                    iteration_count <= 3'd0;\n                    edge_index <= 4'd0;\n                    next_state <= RELAX_FORWARD;\n                end\n                \n                RELAX_FORWARD: begin\n                    if (edge_index < num_edges) begin\n                        if (dist_s[u[edge_index]] != 32'hFFFF_FFFF) begin\n                            if ((dist_s[u[edge_index]] + {16'd0, w[edge_index]}) < dist_s[v[edge_index]]) begin\n                                dist_s[v[edge_index]] <= dist_s[u[edge_index]] + {16'd0, w[edge_index]};\n                                num_paths_s[v[edge_index]] <= num_paths_s[u[edge_index]];\n                            end else if ((dist_s[u[edge_index]] + {16'd0, w[edge_index]}) == dist_s[v[edge_index]]) begin\n                                num_paths_s[v[edge_index]] <= num_paths_s[v[edge_index]] + num_paths_s[u[edge_index]];\n                            end\n                        end\n                        edge_index <= edge_index + 1;\n                        next_state <= RELAX_FORWARD;\n                    end else begin\n                        edge_index <= 4'd0;\n                        if (iteration_count < 3'd6) begin\n                            iteration_count <= iteration_count + 1;\n                            next_state <= RELAX_FORWARD;\n                        end else begin\n                            total_dist <= dist_s[t];\n                            next_state <= INIT_BACKWARD;\n                        end\n                    end\n                end\n                \n                INIT_BACKWARD: begin\n                    for (i = 0; i < 8; i = i+1) begin\n                        if (i == t) begin\n                            dist_t[i] <= 32'd0;\n                            num_paths_t[i] <= 32'd1;\n                        end else begin\n                            dist_t[i] <= 32'hFFFF_FFFF;\n                            num_paths_t[i] <= 32'd0;\n                        end\n                    end\n                    iteration_count <= 3'd0;\n                    edge_index <= 4'd0;\n                    next_state <= RELAX_BACKWARD;\n                end\n                \n                RELAX_BACKWARD: begin\n                    if (edge_index < num_edges) begin\n                        if (dist_t[v[edge_index]] != 32'hFFFF_FFFF) begin\n                            if ((dist_t[v[edge_index]] + {16'd0, w[edge_index]}) < dist_t[u[edge_index]]) begin\n                                dist_t[u[edge_index]] <= dist_t[v[edge_index]] + {16'd0, w[edge_index]};\n                                num_paths_t[u[edge_index]] <= num_paths_t[v[edge_index]];\n                            end else if ((dist_t[v[edge_index]] + {16'd0, w[edge_index]}) == dist_t[u[edge_index]]) begin\n                                num_paths_t[u[edge_index]] <= num_paths_t[u[edge_index]] + num_paths_t[v[edge_index]];\n                            end\n                        end\n                        edge_index <= edge_index + 1;\n                        next_state <= RELAX_BACKWARD;\n                    end else begin\n                        edge_index <= 4'd0;\n                        if (iteration_count < 3'd6) begin\n                            iteration_count <= iteration_count + 1;\n                            next_state <= RELAX_BACKWARD;\n                        end else begin\n                            next_state <= CHECK_NODES;\n                        end\n                    end\n                end\n                \n                CHECK_NODES: begin\n                    if (dist_s[node_index] + dist_t[node_index] == total_dist) begin\n                        if ((num_paths_s[node_index] * num_paths_t[node_index]) == num_paths_s[t]) begin\n                            mask[node_index] <= 1'b1;\n                        end else begin\n                            mask[node_index] <= 1'b0;\n                        end\n                    end else begin\n                        mask[node_index] <= 1'b0;\n                    end\n                    if (node_index < 3'd7) begin\n                        node_index <= node_index + 1;\n                        next_state <= CHECK_NODES;\n                    end else begin\n                        node_index <= 3'd0;\n                        next_state <= DONE;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule